internal class GUPPriceEngineJournalLineAggregationObject
{

    // List<GUPPriceEngineSalesLinePriceComponentJournalLine>.
    // Stores all compete journal lines -- lines with exactly same AttributeHeaderGroup + AttributeLineGroup
    List journalLineList;

    // All journal lines within the aggregation object.
    Set journalLineRecIdSet;

    // Different for each price term code,
    // within that, always same for each header + line attribute group combination.
    int journalLinePriority = 0;

    // Must be with same currency, multiply by 1000 to remove decimal. 
    real lowestPrice = 0;

    // Length of journalLineList
    int lineCount = 0;

}

Method.Source:
    public void new ()
    {
        this.journalLineList = new List(Types::AnyType);
        this.journalLineRecIdSet = new Set(Types::Int64);

        // For margin component, this should be re-calculated from previous computation result.
        // In that case, GUPPriceEngineJournalLineAggregationObject needs to be re-created during filter phase.
        this.lowestPrice = realMax();           
    }

public static GUPPriceEngineJournalLineAggregationObject getTestInstance(int _journalLinePriority, real _lowestPrice)
{
    GUPPriceEngineJournalLineAggregationObject obj = new GUPPriceEngineJournalLineAggregationObject();
    obj.journalLinePriority = _journalLinePriority;
    obj.lowestPrice = _lowestPrice;
    return obj;
}

    public void addCompeteJournalLineAsSpecificLine(GUPPriceEngineJournalLineObject _journalLine, int _linePriority, real _linePrice)
    {
        journalLineRecIdSet.add(_journalLine.parmJournalLineRecId());
        
        GUPPriceEngineSalesLinePriceComponentJournalLine specificLine = 
            GUPPriceEngineSalesLinePriceComponentJournalLine::newInstanceByJournalLine(_linePrice, _journalLine);
        journalLineList.addEnd(specificLine);

        this.lineCount ++;

        this.journalLinePriority = _linePriority;
        if(_linePrice < this.lowestPrice)
        {
            this.lowestPrice = _linePrice;
        }

    }

public void sortJournalLineList()
{
    GUPListSorter listSorter = GUPListSorter::getInstance();
    GUPComparatorJournalLineObject journalComparator = new GUPComparatorJournalLineObject();
    this.journalLineList = listSorter.sortList(this.journalLineList, journalComparator);
}
